scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var hits = new global.EcsSecrets(new global.EcsAst(engine.rootNode)).hardcodedCredentials();
    var report = new global.EcsReport(engine, {
        ruleId: 'SEC-001',
        title: 'Hardcoded credential',
        recommendation: 'Remove the credential from the script and rotate it, since it is exposed in update sets, ' +
            'version history and exports. Store it in a Credential record used through a Connection & Credential ' +
            'alias or a REST Message authentication profile, or in an encrypted (password2) system property read ' +
            'at run time.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
